<?php /** @var string $k @var array $def @var array $rows @var array $f @var array $departments @var array $refs @var array $maturity */ require __DIR__ . '/_fmt.php'; $base = url('registers') . '?r=' . $k; ?>
<div class="page-head"><div><h1><?= icon($def['icon']) ?> <?= e(t(sprintf('reg.%s', $k))) ?></h1><p class="sub"><?= e(t(sprintf('reg.%s_desc', $k))) ?></p></div>
<div class="actions"><a class="btn secondary" href="<?= e(url('registers')) ?>"><?= e(t('reg.all')) ?></a><?php if (can('rm.work')): ?><a class="btn gold" href="<?= e(url('registers/new') . '?r=' . $k) ?>"><?= e(t('reg.new')) ?></a><?php endif; ?></div></div>
<div class="card notice"><p><?= e(t(sprintf('reg.%s_hint', $k))) ?></p></div>
<?php if (!empty($def['template']) && can('rm.work')): ?><form method="post" action="<?= e(url('registers/template')) ?>" class="card form-grid" novalidate><?= csrf_field() ?><input type="hidden" name="r" value="<?= e($k) ?>">
<?= ff('number', 'year', 'reg.f_year', (int)date('Y') + ($k === 'committee_plan' && date('n') >= 10 ? 1 : 0), ['required' => true, 'extra' => ' min="2000" max="2100"']) ?><div class="field"><button class="btn small" type="submit"><?= e(t(sprintf('reg.template_%s', $k))) ?></button></div></form><?php endif; ?>
<form method="get" action="<?= e(url('registers')) ?>" class="filters"><input type="hidden" name="r" value="<?= e($k) ?>">
<div class="field"><label for="q"><?= e(t('common.search')) ?></label><input type="text" id="q" name="q" value="<?= e($f['q']) ?>"></div>
<div class="field"><label for="status"><?= e(t('reg.status')) ?></label><select id="status" name="status"><option value=""><?= e(t('common.all')) ?></option><?php foreach ($def['statuses'] as $s): ?><option value="<?= e($s) ?>"<?= sel($f['status'], $s) ?>><?= e(t('enum.rgst.' . $s)) ?></option><?php endforeach; ?></select></div>
<div class="field"><label for="dept"><?= e(t('reg.department')) ?></label><select id="dept" name="dept"><option value=""><?= e(t('common.all')) ?></option><?php foreach ($departments as $d): ?><option value="<?= (int)$d['id'] ?>"<?= sel((string)$f['dept'], (string)$d['id']) ?>><?= e(lname($d)) ?></option><?php endforeach; ?></select></div>
<?php if ($def['ref']): ?><div class="field"><label for="ref"><?= e(t(sprintf('reg.ref_%s', $def['ref']))) ?></label><select id="ref" name="ref"><option value=""><?= e(t('common.all')) ?></option><?php foreach ($refs as $id => $l): ?><option value="<?= (int)$id ?>"<?= sel((string)$f['ref'], (string)$id) ?>><?= e(mb_strimwidth($l, 0, 80, '…')) ?></option><?php endforeach; ?></select></div><?php endif; ?>
<?php if ($def['due']): ?><div class="field"><label><input type="checkbox" name="overdue" value="1"<?= $f['overdue'] ? ' checked' : '' ?>> <?= e(t('reg.overdue_only')) ?></label></div><?php endif; ?>
<div class="field"><button class="btn small" type="submit"><?= e(t('common.filter')) ?></button> <a href="<?= e($base) ?>"><?= e(t('common.reset')) ?></a></div></form>
<?php if ($k === 'requirements' && $f['ref']): $by = array_count_values(array_column($rows, 'status')); $app = count($rows) - ($by['not_applicable'] ?? 0); ?>
<div class="card"><strong><?= e(t('reg.matrix_summary')) ?>:</strong> <?= e(t('reg.matrix_line', ['c' => $by['compliant'] ?? 0, 'p' => $by['partial'] ?? 0, 'n' => ($by['not_started'] ?? 0) + ($by['in_progress'] ?? 0), 'a' => $app])) ?><?= $app ? ' — ' . (int)round(100 * (($by['compliant'] ?? 0) + 0.5 * ($by['partial'] ?? 0)) / $app) . '%' : '' ?></div><?php endif; ?>
<div class="table-wrap"><table class="data"><thead><tr><th><?= e(t('reg.code')) ?></th><th><?= e(t('reg.f_title')) ?></th><?php foreach ($def['list'] as $c): ?><th><?= e(t(sprintf('reg.f_%s', $c))) ?></th><?php endforeach; ?><?php if ($def['ref']): ?><th><?= e(t(sprintf('reg.ref_%s', $def['ref']))) ?></th><?php endif; ?><th><?= e(t('reg.department')) ?></th><?php if ($def['due']): ?><th><?= e(t($def['due'])) ?></th><?php endif; ?><th><?= e(t('reg.status')) ?></th></tr></thead><tbody>
<?php if (!$rows): ?><tr><td colspan="9" class="muted"><?= e(t('reg.empty')) ?></td></tr><?php endif; ?>
<?php foreach ($rows as $r): ?><tr><td class="nowrap"><a href="<?= e(url('registers/' . $r['id'])) ?>"><?= e($r['code']) ?></a></td><td><?= e($r['title']) ?></td><?php foreach ($def['list'] as $c): ?><td><?= $val($c, $def['fields'][$c], $r['d'][$c] ?? null) ?></td><?php endforeach; ?>
<?php if ($def['ref']): ?><td><?= $r['ref_id'] ? e(mb_strimwidth($refs[(int)$r['ref_id']] ?? '#' . $r['ref_id'], 0, 40, '…')) : '—' ?></td><?php endif; ?><td><?= e(lname(['name_ar' => $r['dept_ar'], 'name_en' => $r['dept_en']]) ?: '—') ?></td>
<?php if ($def['due']): ?><td class="nowrap"><?= e(fdate($r['due_date']) ?: '—') ?><?= $r['overdue'] ? ' <span class="badge danger">' . e(t('reg.overdue')) . '</span>' : '' ?></td><?php endif; ?><td><?= $st($r['status']) ?></td></tr><?php endforeach; ?></tbody></table></div>
